    def shortestWay(self, source: str, target: str) -> int:
        source_chars = set(source)
        for char in target:
            if char not in source_chars:
                return -1

        count = 0
        target_index = 0
        target_len = len(target)

        while target_index < target_len:
            source_index = 0
